/* src/mdbp_runtime.c -- the token vector, the derivation buffer, yylex, and
 * the only #include of the generated build/mdbp_tables.h.
 *
 * Nothing here knows anything about bison's internals (that is
 * src/parser_glue.c's job) and nothing here knows anything about the CLI
 * (src/mdbparse.c's job).
 */
#include <stdlib.h>
#include <string.h>

#include "mdbp_internal.h"

/* Generated by tools/gen_tables.py inside tools/extract.sh, from
 * build/parser.h + build/grammar.xml + build/rule-map.json, and checked
 * against corpus/grammar-model.json before it is written.  Never
 * hand-written: a hand-written table is how you get a silent off-by-one
 * against 800 terminals that still compiles and still parses most inputs. */
#include "mdbp_tables.h"

/* --- the generated tables ------------------------------------------------ */

/* PLAN.md P2.1 (D-5): `mdbp_terminal.name` is now a fixed-size `char[]`
 * embedded in the struct, not a `const char *`, so that mdbp_terminals[]
 * carries no pointer needing a load-time relocation and lands in .rodata.
 * strncmp(), bounded by the field's own width, is the adjustment that fits:
 * every entry the generator writes is NUL-terminated well inside that width
 * (gen_tables.py sizes it to the longest name plus one), so this is exactly
 * strcmp() for every real comparison, but it never reads past the embedded
 * array even if that invariant were ever violated -- strcmp() alone would
 * have had no such bound. */
static int mdbp_terminal_cmp(const void *key, const void *element)
{
    const mdbp_terminal *terminal = (const mdbp_terminal *) element;
    return strncmp((const char *) key, terminal->name, sizeof terminal->name);
}

int mdbp_token_number(const char *name)
{
    const mdbp_terminal *hit;

    if (name == NULL) {
        return -1;
    }
    /* mdbp_terminals[] is generated sorted by strcmp order, so this is
     * O(log n) over the 800 terminals -- the parser resolves every token of
     * every record through it. */
    hit = (const mdbp_terminal *) bsearch(name, mdbp_terminals,
                                          MDBP_TERMINAL_COUNT,
                                          sizeof mdbp_terminals[0],
                                          mdbp_terminal_cmp);
    return hit == NULL ? -1 : hit->token_number;
}

const char *mdbp_symbol_name(int kind)
{
    if (kind < 0 || kind >= MDBP_SYMBOL_KIND_COUNT) {
        return NULL;
    }
    /* PLAN.md P2.1 (D-5): the hole bison's own $undefined leaves (the model
     * carries no name for it) is gen_tables.py's empty string, not a null
     * pointer -- a fixed-size char[] has no null to store.  No terminal name
     * is ever empty, so this test is unambiguous, and every caller's
     * `!= NULL` check (src/parser_glue.c) keeps working unchanged. */
    return mdbp_symbol_names[kind][0] == '\0' ? NULL : mdbp_symbol_names[kind];
}

int mdbp_rule_for_serial(int serial)
{
    if (serial < 0 || serial >= MDBP_SERIAL_COUNT) {
        return -1;
    }
    return mdbp_serial_to_rule[serial];
}

size_t mdbp_terminal_count(void)
{
    return (size_t) MDBP_TERMINAL_COUNT;
}

size_t mdbp_serial_count(void)
{
    return (size_t) MDBP_SERIAL_COUNT;
}

/* --- parsing_place (task P1.1) -------------------------------------------- */

/* The enum's names, indexed by its own values, so the two cannot disagree:
 * a reordered src/stub.h moves this table with it.  PARSING_PLACE_SIZE is
 * excluded on purpose -- it is a count, not a place. */
static const char *const mdbp_parsing_place_names[] = {
    "NO_MATTER", "IN_HAVING", "SELECT_LIST", "IN_WHERE", "IN_ON",
    "IN_GROUP_BY", "IN_ORDER_BY", "IN_UPDATE_ON_DUP_KEY", "IN_PART_FUNC",
    "BEFORE_OPT_LIST", "AFTER_LIST", "FOR_LOOP_BOUND", "IN_RETURNING",
};

const char *mdbp_parsing_place_name(int place)
{
    if (place < 0 || place >= (int) PARSING_PLACE_SIZE) {
        return NULL;
    }
    return mdbp_parsing_place_names[place];
}

int mdbp_parsing_place_by_name(const char *name)
{
    int place;

    if (name == NULL) {
        return -1;
    }
    for (place = 0; place < (int) PARSING_PLACE_SIZE; place++) {
        if (strcmp(name, mdbp_parsing_place_names[place]) == 0) {
            return place;
        }
    }
    return -1;
}

size_t mdbp_parsing_place_count(void)
{
    return (size_t) PARSING_PLACE_SIZE;
}

/* --- the context --------------------------------------------------------- */

void mdbp_ctx_init(mdbp_ctx *ctx, const mdbp_token *tokens, size_t ntokens,
                   int want_derivation)
{
    memset(ctx, 0, sizeof *ctx);
    /* The lifted grammar actions (task P1.1) reach the field through five
     * spellings, two of them via `thd->lex`, which build/yy_stub.yy's
     * prologue resolves to `ctx->ctx`.  Set it HERE, once, where the struct
     * is made: an mdbp_ctx with a NULL self-pointer would segfault in the
     * first action that runs, not at some later boundary. */
    ctx->ctx = ctx;
    ctx->current_select = &ctx->own_select;
    ctx->tokens = tokens;
    ctx->ntokens = ntokens;
    ctx->lookahead_index = 0;
    ctx->want_derivation = want_derivation;
    ctx->error_state = -1;
}

void mdbp_ctx_reset(mdbp_ctx *ctx, const mdbp_token *tokens, size_t ntokens)
{
    ctx->tokens = tokens;
    ctx->ntokens = ntokens;
    /* Back to our OWN storage, and back to NO_MATTER.  The previous record
     * may have been a live parse, in which case current_select pointed into a
     * lexer this record's caller has already freed; mdbp_parse_sql() re-points
     * it at the new one after mdbp_lex_new(). */
    ctx->current_select = &ctx->own_select;
    ctx->own_select.parsing_place = NO_MATTER;
    ctx->own_select.save_parsing_place = NO_MATTER;
    /* Cleared, not kept: a batch run mixes records that carry SQL (the pull
     * path) with records that carry a token vector, and a stale source from
     * the previous line would make this one ignore its own tokens.  The
     * caller re-arms it with mdbp_ctx_set_source() after every reset. */
    ctx->source = NULL;
    ctx->source_user = NULL;
    ctx->cursor = 0;
    ctx->lookahead_index = 0;
    /* the buffer and its capacity STAY; only the length goes back to zero */
    ctx->nderivation = 0;
    ctx->internal_error = 0;
    ctx->error_seen = 0;
    ctx->error_state = -1;
    ctx->error_message = NULL;
    /* parser_glue.c mallocs this per rejected parse: hand it back now or the
     * batch run leaks monotonically over the corpus's rejections. */
    free((void *) ctx->expected);
    ctx->expected = NULL;
    ctx->nexpected = 0;
}

void mdbp_ctx_free(mdbp_ctx *ctx)
{
    free(ctx->derivation);
    ctx->derivation = NULL;
    ctx->derivation_cap = 0;
    ctx->nderivation = 0;
    free((void *) ctx->expected);
    ctx->expected = NULL;
    ctx->nexpected = 0;
}

/* --- the derivation ------------------------------------------------------ */

void mdbp_reduce(mdbp_ctx *ctx, int serial)
{
    int rule;

    if (!ctx->want_derivation || ctx->internal_error) {
        return;
    }
    rule = mdbp_rule_for_serial(serial);
    if (rule < 0) {
        /* Unreachable unless the tables and the parser disagree, which
         * gen_tables.py fails closed on -- but silence is not an option
         * here, so it becomes an internal error rather than a wrong
         * derivation. */
        ctx->internal_error = 1;
        return;
    }
    if (ctx->nderivation == ctx->derivation_cap) {
        size_t want = ctx->derivation_cap ? ctx->derivation_cap * 2 : 256;
        int *grown = (int *) realloc(ctx->derivation, want * sizeof *grown);
        if (grown == NULL) {
            ctx->internal_error = 1;
            return;
        }
        ctx->derivation = grown;
        ctx->derivation_cap = want;
    }
    ctx->derivation[ctx->nderivation++] = rule;
}

/* --- the lexer ----------------------------------------------------------- */

void mdbp_ctx_set_source(mdbp_ctx *ctx, mdbp_source_fn source, void *user)
{
    ctx->source = source;
    ctx->source_user = user;
}

int yylex(int *lvalp, mdbp_ctx *ctx)
{
    /* The value stack is unused (every action is a stub), but bison copies
     * *lvalp onto it, so it must be initialised. */
    *lvalp = 0;

    if (ctx->source != NULL) {
        /* THE PULL PATH (`--valid live`): the parser drives the lexer, so the
         * token does not exist until this call asks for it.  This is the only
         * way valid(T) can be answered from the live LR stack -- the lexer's
         * decision and the parser's state are the same instant -- and it is
         * what MariaDB itself does.
         *
         * A source that ends (0) or fails (-1) both return bison's $end: the
         * parse has to stop either way, and the CALLER, not this function,
         * decides what the failure means (an unknown terminal name is a
         * verdict of "unsupported", an allocation failure is "internal").
         * ctx->cursor keeps counting handed-over tokens exactly as below, so
         * error.at_index indexes the caller's token vector unchanged. */
        mdbp_token tok;
        int rc = ctx->source(ctx->source_user, &tok);

        if (rc <= 0) {
            ctx->lookahead_index = ctx->cursor;
            return 0;
        }
        ctx->lookahead_index = ctx->cursor++;
        return tok.token_number;
    }

    if (ctx->cursor >= ctx->ntokens) {
        /* The synthetic end of input.  It is NOT counted in cursor, and
         * lookahead_index becomes ntokens, which is what error.at_index
         * reports when the failure is at end of input. */
        ctx->lookahead_index = ctx->ntokens;
        return 0;
    }
    ctx->lookahead_index = ctx->cursor;
    return ctx->tokens[ctx->cursor++].token_number;
}
